<?php $starterHashes=require APP_ROOT.'/includes/control-starter.php';$activeControl=qone('SELECT username,pass_hash FROM control_users WHERE id=?',[control_user()['id']]);$starterControl=$activeControl&&hash_equals($starterHashes['username_hash'],$activeControl['username'])&&hash_equals($starterHashes['password_hash'],$activeControl['pass_hash']); ?>
<form id="control-credentials-form"><?php if($starterControl):?><p class="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">تنبيه: بيانات دخول افتراضية. غيّر اسم المستخدم وكلمة المرور الآن قبل استقبال الزوار.</p><?php endif;?><p role="alert" id="cc-error" hidden class="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"></p><div class="mt-6 grid gap-5 sm:grid-cols-2">
<?php foreach([['newUsername','اسم المستخدم الجديد (اختياري)','text','اتركه فارغاً للإبقاء على الاسم الحالي'],['password','كلمة المرور الحالية','password',''],['newPassword','كلمة المرور الجديدة (اختياري)','password','16 حرفاً على الأقل. اتركها فارغة لتغيير اسم المستخدم فقط.'],['confirmation','تأكيد كلمة المرور الجديدة','password','']]as[$name,$label,$type,$hint]):?>
<label class="block text-sm font-bold"><?=e($label)?><input class="mt-2 block w-full rounded-xl border border-neutral-300 bg-white p-3 text-sm" type="<?=$type?>" name="<?=$name?>" dir="ltr" autocomplete="<?=$name==='password'?'current-password':($type==='password'?'new-password':'off')?>" <?=$name==='password'?'required':''?>><?php if($hint):?><span class="mt-1 block text-xs font-normal leading-6 text-neutral-500"><?=e($hint)?></span><?php endif;?></label><?php endforeach;?>
<?php if($credentialEnabled):?><label class="block text-sm font-bold">رمز المصادقة أو الاسترداد<input class="mt-2 block w-full rounded-xl border border-neutral-300 bg-white p-3 text-sm" name="code" dir="ltr" autocomplete="one-time-code" required><span class="mt-1 block text-xs font-normal leading-6 text-neutral-500">مطلوب لأن المصادقة بخطوتين مفعلة لهذا الحساب.</span></label><?php endif;?></div>
<div class="mt-5 rounded-2xl border border-neutral-100 bg-neutral-50 p-4 text-xs leading-7">🔒 تُحفظ بصمات آمنة فقط، ولا يمكن عرض كلمة المرور بعد الحفظ.<br>بعد التغيير تنتهي جميع جلسات الكنترول، ثم تسجل الدخول بالبيانات الجديدة. احتفظ برموز الاسترداد في مكان خاص.</div><div class="mt-5 flex flex-wrap items-center justify-between gap-4"><button class="rounded-full bg-black px-6 py-3 text-sm font-bold text-white disabled:opacity-40">حفظ البيانات وتسجيل الخروج ←</button><span class="text-xs text-neutral-500">يجب تغيير حقل واحد على الأقل. لن يتم تغيير إعدادات المتجر.</span></div></form>
<div id="cc-success" hidden role="status" class="mt-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-8 text-center text-emerald-800"><div class="text-3xl">✓</div><h3 class="mt-3 text-xl font-black">تم تحديث بيانات الدخول</h3><p class="my-4 text-sm leading-7">انتهت جميع جلسات الكنترول القديمة، بما فيها هذه الجلسة.<br>إعدادات المصادقة بخطوتين ورموز الاسترداد لم تتغير.</p><a href="<?=e(url('control/login.php'))?>" class="inline-block rounded-full bg-black px-6 py-3 text-sm font-bold text-white">تسجيل الدخول بالبيانات الجديدة ←</a></div></section>
<script>(()=>{const f=document.getElementById('control-credentials-form'),err=document.getElementById('cc-error');f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button'),data=Object.fromEntries(new FormData(f));data.csrf=<?=json_encode($_SESSION['auth_csrf'])?>;btn.disabled=true;err.hidden=true;try{const r=await fetch(<?=json_encode(url('control/credentials.php'))?>,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();for(const el of f.querySelectorAll('input[type=password],input[name=code]'))el.value='';if(r.ok){window.dispatchEvent(new Event('control-credentials-changed'));f.reset();f.hidden=true;document.getElementById('cc-success').hidden=false;}else{err.textContent=d.error||'تعذر الحفظ';err.hidden=false;}}catch{err.textContent='تعذر الاتصال. تحقق من حالة الدخول قبل إعادة المحاولة.';err.hidden=false;}finally{btn.disabled=false;}};})();</script>
